        // ra_term_nodes.push(node_term_012.child[0]);
        //
        // if ( ra_term_nodes.length == 0)
        // { throw Error("Error: Trap internal error (f54d7dc0_70412575)!\n"); }
        // // elsif ( ra_term_nodes.length == 1)
